async function consumeFullStream(fullStream, initialMsg, syncMsg) {
  let msg = initialMsg;
  let text2 = msg.text();
  let thinking = null;
  let thinkTime = 0;
  let fullResponse = "";
  try {
    for await (const chunk of fullStream) {
      if (syncMsg) {
        const newMsg = syncMsg();
        if (newMsg !== msg) {
          msg = newMsg;
          text2 = msg.text();
        }
      }
      if (chunk.type === "reasoning-start") {
        thinkTime = Date.now();
        thinking = msg.thinking("\u601D\u8003\u4E2D...");
      } else if (chunk.type === "reasoning-delta") {
        thinking?.append(chunk.text);
      } else if (chunk.type === "reasoning-end") {
        thinkTime = Date.now() - thinkTime;
        thinking?.updateTitle(`\u601D\u8003\u5B8C\u6BD5\uFF08${(thinkTime / 1e3).toFixed(1)} \u79D2\uFF09`);
        thinking?.complete();
        thinking = null;
      } else if (chunk.type === "text-delta") {
        text2.append(chunk.text);
        fullResponse += chunk.text;
      } else if (chunk.type === "error") {
        throw chunk.error;
      } else if (chunk.type == "finish") {
        break;
      }
    }
    text2.complete();
    msg.complete();
  } catch (err) {
    thinking?.complete();
    const errMsg = err?.message ?? String(err);
    text2.append(errMsg);
    text2.error();
    msg.error();
    throw err;
  }
  return fullResponse;
}
function removeAllXmlTags(text2) {
  text2 = text2.replace(/<([a-zA-Z][\w-]*)(\s+[^>]*)?>([\s\S]*?)<\/\1>/g, "");
  text2 = text2.replace(/<([a-zA-Z][\w-]*)(\s+[^>]*)?\/>/g, "");
  text2 = text2.replace(/<\/?[a-zA-Z][\w-]*(\s+[^>]*)?>/g, "");
  return text2.trim();
}
function buildSkillPrompt(skills) {
  const skillEntries = skills.map((s) => `  <skill>
    <name>${s.name}</name>
    <description>${s.description}</description>
  </skill>`).join("\n");
  return `
<available_skills>
${skillEntries}
</available_skills>`;
}
async function useProductionSkills(artName, storyName) {
  const productionPath = utils_default2.getPath(["skills", "production_skills"]);
  const [artSections, storySections, productionSkillList] = await Promise.all([
    getDirectorSkillSections("art", artName),
    getDirectorSkillSections("story", storyName),
    scanSkills(productionPath + "/*.md")
  ]);
  const mainSkills = [];
  for (const { sectionKey, content } of [...artSections, ...storySections]) {
    const parsed = parseFrontmatter(content);
    mainSkills.push({ path: `skill_manual://${sectionKey}`, content, ...parsed });
  }
  for (const skillPath of productionSkillList) {
    if (!fs7.existsSync(skillPath)) throw new Error(`\u4E3B\u6280\u80FD\u6587\u4EF6\u4E0D\u5B58\u5728: ${skillPath}`);
    const content = await fs7.promises.readFile(skillPath, "utf-8");
    const parsed = parseFrontmatter(content);
    mainSkills.push({ path: skillPath, ...parsed });
  }
  const res = {
    prompt: `## Skills
\u4EE5\u4E0B\u6280\u80FD\u63D0\u4F9B\u4E86\u4E13\u4E1A\u4EFB\u52A1\u7684\u4E13\u7528\u6307\u4EE4\u3002
\u5F53\u4EFB\u52A1\u4E0E\u67D0\u4E2A\u6280\u80FD\u7684\u63CF\u8FF0\u5339\u914D\u65F6\uFF0C\u8C03\u7528 activate_skill \u5DE5\u5177\u5E76\u4F20\u5165\u6280\u80FD\u540D\u79F0\u6765\u52A0\u8F7D\u5B8C\u6574\u6307\u4EE4\u3002
${buildSkillPrompt(mainSkills)}`,
    tools: createSkillTools(mainSkills, { mainSkill: mainSkills, secondarySkills: [], tertiarySkills: [] })
  };
  return res;
}

