                throw new QuickVideoError("STORYBOARD_LOCKED", "\u5206\u955C\u4E0D\u5B58\u5728\u6216\u5DF2\u786E\u8BA4\u9501\u5B9A\uFF0C\u4E0D\u5141\u8BB8\u7ED1\u5B9A\u8D44\u4EA7", s.version);
